namespace App\Models; use Illuminate\Database\Eloquent\Model; class ServiceBooking extends Model { protected $fillable=['business_id','service_id','user_id','customer_name','customer_phone','customer_email','address','city','locality','pincode','latitude','longitude','booking_date','booking_time','problem_description','status','quoted_amount','business_notes']; protected $casts=['booking_date'=>'date','quoted_amount'=>'float','latitude'=>'float','longitude'=>'float']; public function service(){return $this->belongsTo(Service::class);} public function business(){return $this->belongsTo(Business::class);} }
